from pathlib import Path
import json,collections
b=Path('treinamentos/crescimento_photopea_v2')
for p in sorted((b/'auditoria/execucao').glob('*.jsonl')):
    entries=[];errors=[]
    for i,line in enumerate(p.read_text(encoding='utf-8-sig').splitlines(),1):
        try:entries.append(json.loads(line))
        except Exception as e:errors.append({'line':i,'error':str(e)})
    print(json.dumps({'diary':str(p.relative_to(b)).replace(chr(92),'/'),'entries':len(entries),'errors':errors,'first_keys':list(entries[0]) if entries else [],'last_keys':list(entries[-1])if entries else []},ensure_ascii=False))
for p in sorted((b/'auditoria/prompts').glob('*.json')):
    d=json.loads(p.read_text(encoding='utf-8-sig'))
    print(json.dumps({'prompt_file':p.name,'keys':list(d) if isinstance(d,dict) else 'list','model_fields':{k:v for k,v in d.items() if 'model'in k.lower() or 'effort'in k.lower()}if isinstance(d,dict)else{}},ensure_ascii=False))
for name in ['checagem_extracao_bases.json','verificacao_bases_montagem.json','teste_criacao_resultado.json','teste_dom_basico.json','teste_echo.json','teste_exportar_png.json','teste_exportar_psd.json','teste_psb_embutido.json','teste_reabrir_criado.json']:
    p=b/'auditoria'/name;d=json.loads(p.read_text(encoding='utf-8-sig'))
    print(json.dumps({'evidence':name,'data':d if p.stat().st_size<3500 else {k:v for k,v in d.items() if k not in ['layers','files','comparisons','checks']}},ensure_ascii=False))

